//! AI Image Detection: find whether an image, or part of it, was generated by AI.
//!
//! Send the image with [`Client::ai_image_detection`](crate::Client::ai_image_detection) (base64
//! JSON) or [`Client::ai_image_detection_multipart`](crate::Client::ai_image_detection_multipart),
//! or its URL with [`Client::submit_ai_image_detection`](crate::Client::submit_ai_image_detection).

use serde::{Deserialize, Serialize};

use crate::body::{Content, UploadBody};
use crate::common::{Headers, ResultWebhook};
use crate::webhooks::WebhookError;
use crate::{de, validate, Result, ScannedDocument};

/// The AI Image 1 Ultra model. It returns a mask of the AI-generated regions.
pub const AI_IMAGE_1_ULTRA: &str = "ai-image-1-ultra";

/// The file extensions the API accepts.
const EXTENSIONS: [&str; 8] = [
    ".png", ".jpg", ".jpeg", ".bmp", ".webp", ".heic", ".heif", ".avif",
];

/// The most objects [`ObjectDetection`] accepts in one request.
const MAX_OBJECTS: usize = 3;

str_enum! {
    /// The kind of mask returned with the result (`maskType`).
    MaskType {
        /// A run-length encoded mask of the AI-generated regions, in
        /// [`AiImageMask::starts`] and [`AiImageMask::lengths`]. The server default.
        Binary = "binary",
        /// A heatmap: the mask also has [`AiImageMask::labels`], a confidence band from 0 to 4
        /// for each run.
        Heatmap = "heatmap",
        /// No mask: the response has no [`result`](field@AiImageDetectionResponse::result).
        /// Only for the synchronous check, not for
        /// [`Client::submit_ai_image_detection`](crate::Client::submit_ai_image_detection).
        None = "none",
    }
}

/// An object to locate in the image, for example `face`. The response then has a mask for each
/// object found, in [`AiImageDetectionResponse::detected_objects`].
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
#[non_exhaustive]
pub struct ObjectDetection {
    /// The object to locate, 1 to 32 characters, for example `face` or `hand`.
    pub object: String,
}

impl ObjectDetection {
    /// Creates an object to locate.
    pub fn new(object: impl Into<String>) -> Self {
        Self {
            object: object.into(),
        }
    }
}

/// Checks `objectDetection`: 1 to 3 entries, each 1 to 32 characters and not blank.
fn validate_objects(objects: &[ObjectDetection]) -> Result<()> {
    validate::count(objects.len(), "objectDetection", 1, MAX_OBJECTS)?;
    for entry in objects {
        validate::required(&entry.object, "objectDetection[].object")?;
        validate::length(&entry.object, "objectDetection[].object", 1, 32)?;
    }
    Ok(())
}

/// An image to check, for [`Client::ai_image_detection`](crate::Client::ai_image_detection) and
/// [`Client::ai_image_detection_multipart`](crate::Client::ai_image_detection_multipart). At least
/// 512 px on each side, at most 27 megapixels, and under 32 MB.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub struct AiImageDetectionRequest {
    /// The image. Sent base64-encoded as `base64` in JSON, or as the `image` file in multipart.
    #[serde(rename = "base64")]
    content: Content,
    /// File name with extension (`.png`, `.jpg`, `.jpeg`, `.bmp`, `.webp`, `.heic`, `.heif`,
    /// `.avif`), 5 to 254 characters.
    pub filename: String,
    /// The detection model, for example [`AI_IMAGE_1_ULTRA`].
    pub model: String,
    /// Sandbox mode: free mock results, for integration testing.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sandbox: Option<bool>,
    /// The kind of mask to return. Server default: [`MaskType::Binary`].
    #[serde(skip_serializing_if = "Option::is_none")]
    pub mask_type: Option<MaskType>,
    /// Objects to locate in the image, 1 to 3. Does not change the cost of the request.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub object_detection: Option<Vec<ObjectDetection>>,
}

impl AiImageDetectionRequest {
    /// Creates a request from a base64-encoded image.
    pub fn new(
        base64: impl Into<String>,
        filename: impl Into<String>,
        model: impl Into<String>,
    ) -> Self {
        Self::with_content(Content::base64(base64), filename.into(), model.into())
    }

    /// Creates a request from the raw image bytes, taking a `Vec<u8>` without a copy. The bytes
    /// are base64-encoded only when sent as JSON.
    pub fn from_bytes(
        image: impl Into<Vec<u8>>,
        filename: impl Into<String>,
        model: impl Into<String>,
    ) -> Self {
        Self::with_content(Content::raw(image), filename.into(), model.into())
    }

    fn with_content(content: Content, filename: String, model: String) -> Self {
        Self {
            content,
            filename,
            model,
            sandbox: None,
            mask_type: None,
            object_detection: None,
        }
    }

    pub(crate) fn validate(&self) -> Result<()> {
        if self.content.is_empty() {
            return Err(crate::Error::Validation("base64 is required".to_owned()));
        }
        validate::required(&self.model, "model")?;
        validate::length(&self.filename, "filename", 5, 254)?;
        validate::extension(&self.filename, &EXTENSIONS)?;
        if let Some(objects) = &self.object_detection {
            validate_objects(objects)?;
        }
        Ok(())
    }

    pub(crate) fn content(&self) -> &Content {
        &self.content
    }

    pub(crate) fn upload_body(&self) -> Result<UploadBody> {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Rest<'a> {
            filename: &'a str,
            model: &'a str,
            #[serde(skip_serializing_if = "Option::is_none")]
            sandbox: Option<bool>,
            #[serde(skip_serializing_if = "Option::is_none")]
            mask_type: Option<MaskType>,
            #[serde(skip_serializing_if = "Option::is_none")]
            object_detection: Option<&'a [ObjectDetection]>,
        }
        UploadBody::new(
            &self.content,
            &Rest {
                filename: &self.filename,
                model: &self.model,
                sandbox: self.sandbox,
                mask_type: self.mask_type,
                object_detection: self.object_detection.as_deref(),
            },
        )
    }

    /// The text fields of the multipart form, in order: `filename`, `model`, then the optional
    /// `sandbox`, `maskType` and `objectDetection` (a JSON array in one field).
    pub(crate) fn form_fields(&self) -> Result<Vec<(&'static str, String)>> {
        let mut fields = vec![
            ("filename", self.filename.clone()),
            ("model", self.model.clone()),
        ];
        if let Some(sandbox) = self.sandbox {
            fields.push(("sandbox", sandbox.to_string()));
        }
        if let Some(mask_type) = self.mask_type {
            fields.push(("maskType", mask_type.as_str().to_owned()));
        }
        if let Some(objects) = &self.object_detection {
            fields.push(("objectDetection", serde_json::to_string(objects)?));
        }
        Ok(fields)
    }
}

setters!(AiImageDetectionRequest {
    sandbox: bool,
    mask_type: MaskType,
    object_detection: Vec<ObjectDetection>,
});

/// An image URL to check, for
/// [`Client::submit_ai_image_detection`](crate::Client::submit_ai_image_detection).
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub struct AiImageDetectionSubmission {
    /// The public URL of the image.
    pub url: String,
    /// File name with extension (`.png`, `.jpg`, `.jpeg`, `.bmp`, `.webp`, `.heic`, `.heif`,
    /// `.avif`), 4 to 254 characters.
    pub file_name: String,
    /// The detection model, for example [`AI_IMAGE_1_ULTRA`].
    pub model: String,
    /// [`MaskType::Binary`] (server default) or [`MaskType::Heatmap`].
    #[serde(skip_serializing_if = "Option::is_none")]
    pub mask_type: Option<MaskType>,
    /// Objects to locate in the image, 1 to 3.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub object_detection: Option<Vec<ObjectDetection>>,
    /// Headers Copyleaks sends when it fetches the image from `url`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub headers: Option<Headers>,
    /// Where Copyleaks posts the result.
    pub webhooks: ResultWebhook,
    /// Sandbox mode: free mock results, for integration testing.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sandbox: Option<bool>,
    /// A custom string returned with the result. At most 511 characters.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub developer_payload: Option<String>,
}

impl AiImageDetectionSubmission {
    /// Creates a submission of the image at `url`; `webhook_url` receives the result.
    pub fn new(
        url: impl Into<String>,
        file_name: impl Into<String>,
        model: impl Into<String>,
        webhook_url: impl Into<String>,
    ) -> Self {
        Self {
            url: url.into(),
            file_name: file_name.into(),
            model: model.into(),
            webhooks: ResultWebhook::new(webhook_url),
            ..Self::default()
        }
    }

    /// Replaces the webhook, for example to add headers.
    #[must_use]
    pub fn webhooks(mut self, webhooks: ResultWebhook) -> Self {
        self.webhooks = webhooks;
        self
    }

    pub(crate) fn validate(&self) -> Result<()> {
        validate::required(&self.url, "url")?;
        validate::required(&self.model, "model")?;
        validate::length(&self.file_name, "fileName", 4, 254)?;
        validate::extension(&self.file_name, &EXTENSIONS)?;
        validate::required(&self.webhooks.url, "webhooks.url")?;
        if let Some(objects) = &self.object_detection {
            validate_objects(objects)?;
        }
        if let Some(payload) = &self.developer_payload {
            validate::length(payload, "developerPayload", 0, 511)?;
        }
        Ok(())
    }
}

setters!(AiImageDetectionSubmission {
    mask_type: MaskType,
    object_detection: Vec<ObjectDetection>,
    headers: Headers,
    sandbox: bool,
    developer_payload: String,
});

/// The result of AI Image Detection, and the webhook payload of
/// [`Client::submit_ai_image_detection`](crate::Client::submit_ai_image_detection). In a webhook
/// payload, check [`error`](field@Self::error) first.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub struct AiImageDetectionResponse {
    /// Why the detection failed, in a webhook payload; then only the developer payload is also
    /// set. The synchronous calls return an [`Error`](crate::Error) instead.
    pub error: Option<WebhookError>,
    /// The version of the detection model.
    pub model: Option<String>,
    /// The mask of the AI-generated regions. `None` with [`MaskType::None`].
    pub result: Option<AiImageMask>,
    /// The human and AI shares of the image.
    pub summary: Option<AiImageSummary>,
    /// Whether the image was flagged as AI-generated.
    pub is_ai_detected: Option<bool>,
    /// Information about the image.
    pub image_info: Option<ImageInfo>,
    /// The objects found, one entry per requested object that is in the image. Objects that were
    /// not found are left out, so look entries up by [`DetectedObject::object`].
    #[serde(default, deserialize_with = "de::vec_skip_nulls")]
    pub detected_objects: Vec<DetectedObject>,
    /// The developer payload you sent with
    /// [`AiImageDetectionSubmission::developer_payload`](field@AiImageDetectionSubmission::developer_payload).
    pub developer_payload: Option<String>,
    /// General information about the scan.
    pub scanned_document: Option<ScannedDocument>,
}

/// A run-length encoded mask: run `i` starts at pixel `starts[i]` of the flattened image and is
/// `lengths[i]` pixels long.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct AiImageMask {
    /// Start positions of the runs.
    #[serde(default, deserialize_with = "de::null_as_default")]
    pub starts: Vec<i64>,
    /// Lengths of the runs.
    #[serde(default, deserialize_with = "de::null_as_default")]
    pub lengths: Vec<i64>,
    /// With [`MaskType::Heatmap`]: the confidence band of each run, from 0 (lowest) to 4
    /// (highest). `None` for other masks.
    pub labels: Option<Vec<i32>>,
}

/// An object found in the image, from [`AiImageDetectionResponse::detected_objects`].
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct DetectedObject {
    /// The object from the request, for example `face`.
    pub object: Option<String>,
    /// The run-length encoded mask of the object, in the coordinates of
    /// [`ImageInfo::shape`](field@ImageInfo::shape).
    pub mask: Option<AiImageMask>,
}

/// The shares of the image's pixels, each from 0 to 1.
#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct AiImageSummary {
    /// The share of pixels classified as human-created.
    pub human: Option<f64>,
    /// The share of pixels classified as AI-generated.
    pub ai: Option<f64>,
}

/// Information about the analyzed image.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct ImageInfo {
    /// The image dimensions.
    pub shape: Option<ImageShape>,
    /// Metadata read from the image file, when available.
    pub metadata: Option<ImageMetadata>,
}

/// The image dimensions, in pixels.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub struct ImageShape {
    /// Height in pixels.
    pub height: Option<i64>,
    /// Width in pixels.
    pub width: Option<i64>,
}

/// Metadata read from an image or video file, when available, for example C2PA provenance
/// data.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub struct ImageMetadata {
    /// When the file was created.
    pub issued_time: Option<String>,
    /// The AI service or tool that created the file.
    pub issued_by: Option<String>,
    /// The application or device used to create the file.
    pub app_or_device_used: Option<String>,
    /// A summary of how the file was generated.
    pub content_summary: Option<String>,
}

/// The MIME type of an image file name, for the multipart upload.
pub(crate) fn mime_type(filename: &str) -> &'static str {
    let name = filename.to_ascii_lowercase();
    let extension = name.rsplit('.').next().unwrap_or_default();
    match extension {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "bmp" => "image/bmp",
        "webp" => "image/webp",
        "ico" => "image/x-icon",
        "heic" => "image/heic",
        "heif" => "image/heif",
        "avif" => "image/avif",
        _ => "application/octet-stream",
    }
}
